		return
	}

	const layer = findLayer(store.state, layerId)
	if (!layer) {
		message.scenePlanApplyStatus = 'skipped'
		appendUniqueMessageNote(message, '鍔ㄧ敾鐢熸垚澶辫触锛氭壘涓嶅埌鐩爣鍥惧眰銆?)
		return
	}

	const compiled = compileVideoScenePlan({
		layer,
		insertedNodeIds,
		rootNodeId: insertedNodeIds[0],
