  nanoPreviewSourcePaths?: string[];
  nanoPreviewLoadingStates?: boolean[];
  nanoPreviewDownloadStatuses?: string[];
  nanoPreviewDownloadProgresses?: number[];
  nanoPreviewLocalReadyStates?: boolean[];
  nanoPreviewUrl?: string;
