  if (modelKey.value === 'nanobanana' || modelKey.value === 'seedance') {
    return props.sending ? '鐢熸垚涓€? : '鐢熸垚';
  }
  return props.sending ? '鍙戦€佷腑鈥? : '鍙戦€?;
});

