}

.chat-history-minimize:hover {
  border-color: var(--wf-primary, #1f9d84);
  color: var(--wf-primary, #1f9d84);
  box-shadow: 0 0 8px color-mix(in srgb, var(--wf-primary, #1f9d84) 30%, transparent);
