  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 16px;
  padding: 0 1px;
  margin-top: 0;
  font-size: 11px;
  color: color-mix(in srgb, var(--wf-primary, #1f9d84) 55%, transparent);
