.wf-meshy-target-btn,
.wf-media-btn {
  border: 1px solid rgb(from var(--vscode-border) r g b / 0.88);
  background: linear-gradient(
    180deg,
    rgb(from var(--dweb-defualt-dark) r g b / 0.78),
    rgb(from var(--dweb-defualt) r g b / 0.72)
  );
  color: var(--vscode-fg);
  padding: 8px 10px;
  font-size: 12px;
  cursor: pointer;
  backdrop-filter: blur(8px);
}

.wf-meshy-target-btn.active {
  border-color: rgb(90 180 255 / 0.72);
  box-shadow: 0 0 0 1px rgb(90 180 255 / 0.18), 0 0 16px rgb(90 180 255 / 0.12);
}

.wf-meshy-target-btn:hover,
.wf-media-btn:hover {
  border-color: var(--vscode-hover-border);
}

.wf-meshy-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.wf-meshy-preview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.wf-meshy-preview-card {
  display: grid;
  gap: 6px;
}

.wf-meshy-preview-label {
  font-size: 11px;
  color: #9ec2dd;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.wf-meshy-preview-sub {
  font-size: 11px;
  color: var(--vscode-fg-muted);
  line-height: 1.35;
}

.wf-meshy-preview-empty {
  min-height: 130px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px dashed rgb(from var(--vscode-border) r g b / 0.68);
  color: var(--vscode-fg-muted);
  font-size: 12px;
}

.wf-meshy-summary-card {
  display: grid;
  gap: 6px;
}

.wf-meshy-thumb {
  display: block;
  width: 100%;
  max-height: 220px;
  object-fit: contain;
}

.wf-meshy-row {
  display: grid;
  gap: 10px;
}

.wf-meshy-collapsed-note {
  border: 1px dashed rgb(from var(--vscode-border) r g b / 0.68);
  background: rgb(from var(--dweb-defualt-dark) r g b / 0.42);
  color: var(--vscode-fg-muted);
  font-size: 12px;
  line-height: 1.45;
  padding: 10px 12px;
}

.wf-meshy-field {
  display: grid;
  gap: 6px;
}

.wf-meshy-config-card {
  border: 1px solid rgb(from var(--vscode-border) r g b / 0.85);
  background: rgb(from var(--dweb-defualt-dark) r g b / 0.54);
  padding: 10px;
  gap: 8px;
}

.wf-meshy-config-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.wf-meshy-config-table th,
.wf-meshy-config-table td {
  border: 1px solid rgb(from var(--vscode-border) r g b / 0.68);
  padding: 6px 8px;
  vertical-align: middle;
}

.wf-meshy-config-table th {
  width: 38%;
  text-align: left;
  color: #9ec2dd;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.wf-meshy-switch-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--vscode-fg);
}

.wf-meshy-config-note {
  font-size: 11px;
  color: var(--vscode-fg-muted);
  line-height: 1.4;
}

.wf-meshy-static-value {
  min-height: 34px;
  display: flex;
  align-items: center;
  color: var(--vscode-fg);
  font-size: 12px;
}

.wf-meshy-static-copy {
  align-items: flex-start;
  line-height: 1.45;
}

.wf-meshy-config-inline {
  margin-top: 6px;
  font-size: 11px;
  color: var(--vscode-fg-muted);
}

.wf-meshy-field-wide {
  grid-column: 1 / -1;
}

.wf-meshy-input,
.wf-meshy-textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgb(from var(--vscode-border) r g b / 0.85);
  background: rgb(from var(--dweb-defualt-dark) r g b / 0.72);
  color: var(--vscode-fg);
  padding: 8px 10px;
  font-size: 12px;
  border-radius: 0;
}

.wf-meshy-textarea {
  resize: vertical;
  min-height: 76px;
}

.wf-meshy-textarea.compact {
  min-height: 60px;
}

.wf-meshy-format-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.wf-meshy-format-item {
  justify-content: flex-start;
}

.wf-meshy-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.wf-meshy-hint-shell {
  min-width: 0;
  display: grid;
  gap: 8px;
}

.wf-meshy-followup-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.wf-media-btn-secondary {
  padding: 6px 8px;
  font-size: 11px;
}

.wf-media-btn:disabled {
  opacity: 0.58;
  cursor: not-allowed;
}

@media (max-width: 720px) {
  .wf-meshy-hero,
  .wf-meshy-summary-grid,
  .wf-meshy-target-switch,
  .wf-meshy-preview-grid,
  .wf-meshy-format-grid {
    grid-template-columns: 1fr;
  }
}
</style>

