      ...item,
      previewScaleMode: currentMode === "model" ? "placeholder" : "model",
    } as WorkflowSceneLayoutItem & Record<string, unknown>;
    if (nextItem.fitMode === "forced") {
      delete nextItem.fitMode;
      delete nextItem.fitMessage;
