  });
  lastActionMessage.value = "宸插垏鎹㈣瀵熸瘮渚嬶紱濡傛灉涔嬪墠鍚敤浜嗗己鍒堕€傞厤锛屽綋鍓嶅凡鑷姩娓呴櫎銆俓

update-layout-items", nextItems);
