    const errMessage = isObject(err) && isString(err.message) ? err.message : String(err ?? "unknown");
    lastActionMessage.value = `棰勮鍣ㄥ垵濮嬪寲澶辫触锛?{errMessage}`;
  }
};

const ensureViewer = () => {
  if (viewer || viewerInitPending) {
    return;
  }
  if (!canvasRef.value) return;
  if (Date.now() < viewerInitCooldownUntil) {
    return;
  }
  viewerInitPending = true;
  nextTick(() => {
    if (!viewerInitPending) return;
    viewerInitRaf = requestAnimationFrame(() => {
      viewerInitRaf = 0;
      viewerInitPending = false;
      createViewerNow();
    });
  });
};

const disposeViewer = () => {
  clearViewerInitSchedule();
  viewerInitCooldownUntil = 0;
  stopPerfPolling();
  if (!viewer) return;
  captureSnapshot();
  viewer.dispose();
  viewer = null;
};

const waitForViewerReady = async () => {
  for (let attempt = 0; attempt < 8; attempt += 1) {
    ensureViewer();
    if (viewer) return true;
    await nextTick();
    if (viewer) return true;
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
    if (viewer) return true;
  }
  return false;
};

const startPreviewLoad = async (requestId: number) => {
  activePreviewRequestId = requestId;
  emitPreviewProgress(0.12, "鍒濆鍖栨覆鏌撳櫒");
