  if (activePreviewRequestId !== requestId || !viewer) return;
  viewer.requestStaticFrames();
  await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
  if (activePreviewRequestId !== requestId || !viewer) return;
  captureSnapshot();
  emitPreviewProgress(0.98, "杩涘叆浜や簰鍓嶇姸鎬乗

three-preview-ready");
};

watch(
