    const nextSelectedId = hidePlaceholderCubes.value ? "" : String(value ?? "").trim();
    if (nextSelectedId === selectedPreviewItemId.value) return;
    selectedPreviewItemId.value = nextSelectedId;
    viewer?.setSelectedItem(nextSelectedId);
