      stopPerfPolling();
    }
    viewer?.setInteractive(active);
    if (active) {
      viewer?.setRenderSuspended(previewSuspended.value);
      if (!previewSuspended.value) viewer?.requestStaticFrames();
      refreshPerfSnapshot();
      return;
    }
    if (!previewMode.value) {
      viewer?.requestStaticFrames();
